/*
[演算法邏輯說明]
模擬一個骰子在平面上滾動的過程。
1. 初始狀態：頂面(top)=1, 北面(north)=2, 西面(west)=3。
2. 根據對面之和為 7 的規則，可推導出：底面(bottom)=6, 南面(south)=5, 東面(east)=4。
3. 處理四種滾動指令：
   - north: top 變為新的 north, north 變為新的 bottom, bottom 變為新的 south, south 變為新的 top。
   - south: top 變為新的 south, south 變為新的 bottom, bottom 變為新的 north, north 變為新的 top。
   - east: top 變為新的 east, east 變為新的 bottom, bottom 變為新的 west, west 變為新的 top。
   - west: top 變為新的 west, west 變為新的 bottom, bottom 變為新的 east, east 變為新的 top。
4. 最後輸出頂面(top)的數值。
*/

#include <iostream>
#include <string>

using namespace std;

struct Die {
    int top, bottom, north, south, west, east;
    Die() : top(1), bottom(6), north(2), south(5), west(3), east(4) {}

    void rollNorth() {
        int next_top = south;
        south = bottom;
        bottom = north;
        north = top;
        top = next_top;
    }
    void rollSouth() {
        int next_top = north;
        north = bottom;
        bottom = south;
        south = top;
        top = next_top;
    }
    void rollWest() {
        int next_top = east;
        east = bottom;
        bottom = west;
        west = top;
        top = next_top;
    }
    void rollEast() {
        int next_top = west;
        west = bottom;
        bottom = east;
        east = top;
        top = next_top;
    }
};

int main() {
    int n;
    while (cin >> n && n != 0) {
        Die d;
        for (int i = 0; i < n; ++i) {
            string cmd;
            cin >> cmd;
            if (cmd == "north") d.rollNorth();
            else if (cmd == "south") d.rollSouth();
            else if (cmd == "west") d.rollWest();
            else if (cmd == "east") d.rollEast();
        }
        cout << d.top << endl;
    }
    return 0;
}
